      "target_description": "A subsequent agent action that uses that artifact, value, or resource as an input."
    },
    {
      "name": "APPLIES_OBSERVED_DATA_FORMAT_TO_PROCESSING",
      "definition": "A subsequent processing action is constructed to interpret data according to a format or schema revealed by an earlier observation.",
      "source_description": "An earlier observation that reveals the format or schema of input data.",
      "target_description": "A subsequent data-processing action or code that parses or processes the data according to that observed format."
    },
    {
      "name": "DIAGNOSES_CAUSE_OF_FAILURE",
      "definition": "An agent analyzes an observed execution failure to identify the underlying cause before applying a repair.",
